async function paintedPortrait(page){
 const avatar=page.locator('.hx-tavik-dialogue'),r=await avatar.boundingBox(),v=page.viewportSize(),clip={x:Math.max(0,Math.floor(r.x)),y:Math.max(0,Math.floor(r.y)),width:Math.min(v.width,Math.ceil(r.x+r.width))-Math.max(0,Math.floor(r.x)),height:Math.min(v.height,Math.ceil(r.y+r.height))-Math.max(0,Math.floor(r.y))};
 const styles=await avatar.evaluate(n=>[n,...n.querySelectorAll('*')].map(node=>({visibility:node.style.visibility,animation:node.style.animationPlayState})));let a,b;try{await avatar.evaluate(n=>{for(const node of [n,...n.querySelectorAll('*')])node.style.animationPlayState='paused';});a=PNG.sync.read(await page.screenshot({clip,animations:'allow'}));await avatar.locator('.hx-tavik-dialogue__face').evaluate(n=>n.style.visibility='hidden');b=PNG.sync.read(await page.screenshot({clip,animations:'allow'}));}finally{await avatar.evaluate((n,styles)=>[n,...n.querySelectorAll('*')].forEach((node,i)=>{node.style.visibility=styles[i].visibility;node.style.animationPlayState=styles[i].animation;}),styles);}
 let changed=0;for(let i=0;i<a.data.length;i+=4)if(Math.abs(a.data[i]-b.data[i])+Math.abs(a.data[i+1]-b.data[i+1])+Math.abs(a.data[i+2]-b.data[i+2])>40)changed++;assert(changed>a.width*a.height*.02,'actual screenshot pixels show Tavik’s clipped portrait face ('+changed+' of '+a.width*a.height+')');return changed;
}
